<?php
declare(strict_types=1);
function app_db(): PDO {
 static $pdo=null;
 if(!$pdo)$pdo=new PDO('mysql:host='.DB_HOST.';dbname='.DB_NAME.';charset=utf8mb4',DB_USER,DB_PASS,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);
 return $pdo;
}
function json_out($data,int $status=200):never{http_response_code($status);header('Content-Type: application/json; charset=utf-8');echo json_encode($data,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);exit;}
function request_body():array{$d=json_decode(file_get_contents('php://input'),true);return is_array($d)?$d:[];}
function fail(string $m,int $s=400):never{json_out(['detail'=>$m],$s);}
function esc(string $v):string{return htmlspecialchars($v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function valid_url(string $u):bool{$p=parse_url($u);return is_array($p)&&in_array(strtolower($p['scheme']??''),['http','https'],true)&&!empty($p['host']);}
function request_ip():string{return $_SERVER['REMOTE_ADDR']??'0.0.0.0';}
function make_token(int $n=8):string{$c='abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';$v='';for($i=0;$i<$n;$i++)$v.=$c[random_int(0,strlen($c)-1)];return $v;}
function make_schema(PDO $p):void{
$sqls=[
"CREATE TABLE IF NOT EXISTS users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,username VARCHAR(80) NOT NULL UNIQUE,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role VARCHAR(20) NOT NULL DEFAULT 'user',is_active TINYINT(1) NOT NULL DEFAULT 1,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,last_login DATETIME NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS urls(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,token VARCHAR(62) NOT NULL UNIQUE,label VARCHAR(190) NOT NULL DEFAULT '',target_url TEXT NOT NULL,captcha_enabled TINYINT(1) NOT NULL DEFAULT 1,active TINYINT(1) NOT NULL DEFAULT 1,clicks BIGINT UNSIGNED NOT NULL DEFAULT 0,visits BIGINT UNSIGNED NOT NULL DEFAULT 0,blocked BIGINT UNSIGNED NOT NULL DEFAULT 0,bots BIGINT UNSIGNED NOT NULL DEFAULT 0,captcha_fails BIGINT UNSIGNED NOT NULL DEFAULT 0,last_visit DATETIME NULL,created DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_urls_user_created(user_id,created)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS redirects(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,token VARCHAR(32) NOT NULL UNIQUE,url TEXT NOT NULL,api_key VARCHAR(100) NULL,label VARCHAR(190) NOT NULL DEFAULT '',source VARCHAR(30) NOT NULL DEFAULT 'api',permanent TINYINT(1) NOT NULL DEFAULT 1,expires DATETIME NULL,created DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,clicks BIGINT UNSIGNED NOT NULL DEFAULT 0,visits BIGINT UNSIGNED NOT NULL DEFAULT 0,blocked BIGINT UNSIGNED NOT NULL DEFAULT 0,bots BIGINT UNSIGNED NOT NULL DEFAULT 0,captcha_fails BIGINT UNSIGNED NOT NULL DEFAULT 0,last_visit DATETIME NULL,INDEX idx_redirects_user_created(user_id,created),INDEX idx_redirects_expiry(expires)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS visits(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,token VARCHAR(62) NOT NULL,ip VARCHAR(45) NOT NULL,ua TEXT,device VARCHAR(30),browser VARCHAR(30),os VARCHAR(30),referer TEXT,status VARCHAR(30) NOT NULL,reason VARCHAR(255) NOT NULL DEFAULT '',ts DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_visits_user_ts(user_id,ts),INDEX idx_visits_token_ts(token,ts),INDEX idx_visits_status(status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS link_sessions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,sid VARCHAR(100) NOT NULL UNIQUE,token VARCHAR(62) NOT NULL,target TEXT NOT NULL,expires DATETIME NOT NULL,ip VARCHAR(45) NOT NULL,used TINYINT(1) NOT NULL DEFAULT 0,INDEX idx_link_sessions_expiry(expires)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS blocked_ips(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,ip VARCHAR(45) NOT NULL,reason VARCHAR(255) NOT NULL DEFAULT '',ts DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_block_user_ip(user_id,ip)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS api_keys(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,api_key VARCHAR(100) NOT NULL UNIQUE,label VARCHAR(190) NOT NULL DEFAULT '',active TINYINT(1) NOT NULL DEFAULT 1,usage_count BIGINT UNSIGNED NOT NULL DEFAULT 0,created DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,last_used DATETIME NULL,INDEX idx_api_keys_user(user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
"CREATE TABLE IF NOT EXISTS user_settings(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,setting_key VARCHAR(100) NOT NULL,value_json LONGTEXT NOT NULL,UNIQUE KEY uq_user_setting(user_id,setting_key)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"
];
foreach($sqls as $sql)$p->exec($sql);
$cols=['urls'=>['user_id'=>'BIGINT UNSIGNED NULL'],'redirects'=>['user_id'=>'BIGINT UNSIGNED NULL'],'visits'=>['user_id'=>'BIGINT UNSIGNED NULL'],'blocked_ips'=>['user_id'=>'BIGINT UNSIGNED NULL'],'api_keys'=>['user_id'=>'BIGINT UNSIGNED NULL']];
foreach($cols as $table=>$items)foreach($items as $col=>$def){$q=$p->prepare("SHOW COLUMNS FROM ".$table." LIKE ?");$q->execute([$col]);if(!$q->fetch())$p->exec("ALTER TABLE ".$table." ADD COLUMN ".$col." ".$def);}
 // Older single-admin schemas used a globally unique IP. Make the blocklist user-scoped.
 $idx=$p->query("SHOW INDEX FROM blocked_ips")->fetchAll();$hasComposite=false;$singleIp=[];
 foreach($idx as $row){if($row['Key_name']==='uq_block_user_ip')$hasComposite=true;if((int)$row['Non_unique']===0&&$row['Column_name']==='ip'&&$row['Key_name']!=='PRIMARY')$singleIp[$row['Key_name']]=true;}
 foreach(array_keys($singleIp) as $key)$p->exec("ALTER TABLE blocked_ips DROP INDEX ".$key);
 if(!$hasComposite)$p->exec("ALTER TABLE blocked_ips ADD UNIQUE KEY uq_block_user_ip(user_id,ip)");
}
function session_user():?array{if(empty($_SESSION['user_id']))return null;$q=app_db()->prepare('SELECT id,username,email,role,is_active FROM users WHERE id=? LIMIT 1');$q->execute([(int)$_SESSION['user_id']]);$u=$q->fetch();if(!$u||!(int)$u['is_active']){$_SESSION=[];session_regenerate_id(true);return null;}return $u;}
function require_user():array{$u=session_user();if(!$u)fail('Please log in to continue.',401);return $u;}
function require_admin(array $u):void{if(($u['role']??'')!=='admin')fail('Admin permission required.',403);}
function admin_scope(array $u):bool{$all=($_GET['scope']??'')==='all';if($all)require_admin($u);return $all;}
function device_info(string $ua):array{$v=strtolower($ua);$device=preg_match('/iphone|android|mobile|blackberry/',$v)?'Mobile':(preg_match('/ipad|tablet/',$v)?'Tablet':'Desktop');$browser=str_contains($v,'edg')?'Edge':(str_contains($v,'chrome')?'Chrome':(str_contains($v,'firefox')?'Firefox':(str_contains($v,'safari')?'Safari':'Other')));$os=str_contains($v,'windows')?'Windows':(str_contains($v,'android')?'Android':(str_contains($v,'iphone')||str_contains($v,'ipad')?'iOS':(str_contains($v,'linux')?'Linux':'Other')));return ['device'=>$device,'browser'=>$browser,'os'=>$os];}
function record_visit(string $token,string $status,string $reason=''):void{$p=app_db();$q=$p->prepare('SELECT user_id FROM urls WHERE token=? UNION ALL SELECT user_id FROM redirects WHERE token=? LIMIT 1');$q->execute([$token,$token]);$owner=$q->fetchColumn();$ua=$_SERVER['HTTP_USER_AGENT']??'';$d=device_info($ua);$q=$p->prepare('INSERT INTO visits(user_id,token,ip,ua,device,browser,os,referer,status,reason,ts) VALUES(?,?,?,?,?,?,?,?,?,?,UTC_TIMESTAMP())');$q->execute([$owner,$token,request_ip(),$ua,$d['device'],$d['browser'],$d['os'],$_SERVER['HTTP_REFERER']??'',$status,$reason]);$col=['success'=>'visits','blocked'=>'blocked','bot'=>'bots','captcha_fail'=>'captcha_fails','captcha_pending'=>'clicks'][$status]??null;if($col)foreach(['urls','redirects'] as $tb){$q=$p->prepare("UPDATE ".$tb." SET ".$col."=".$col."+1,last_visit=UTC_TIMESTAMP() WHERE token=?");$q->execute([$token]);}}
function bot_check():array{$ua=$_SERVER['HTTP_USER_AGENT']??'';$v=strtolower($ua);$patterns=['bot','crawl','spider','slurp','googlebot','bingbot','python-requests','curl','wget','scrapy','selenium','puppeteer','playwright','httpx','requests','urllib','semrush','facebookexternalhit','twitterbot','whatsapp','telegram','discordbot','lighthouse','uptimerobot'];if($ua===''||strlen($ua)<20)return [true,'Missing or short User-Agent'];foreach($patterns as $x)if(str_contains($v,$x))return [true,'UA pattern: '.$x];if(!str_starts_with($ua,'Mozilla/')||empty($_SERVER['HTTP_ACCEPT'])||empty($_SERVER['HTTP_ACCEPT_LANGUAGE']))return [true,'Incomplete browser headers'];return [false,''];}
function get_user_setting(int $uid,string $key):?array{$q=app_db()->prepare('SELECT value_json FROM user_settings WHERE user_id=? AND setting_key=?');$q->execute([$uid,$key]);$v=$q->fetchColumn();return $v?json_decode($v,true):null;}
function put_user_setting(int $uid,string $key,array $v):void{$q=app_db()->prepare('INSERT INTO user_settings(user_id,setting_key,value_json) VALUES(?,?,?) ON DUPLICATE KEY UPDATE value_json=VALUES(value_json)');$q->execute([$uid,$key,json_encode($v)]);}
function apply_shortener(string $url,int $uid):string{$c=get_user_setting($uid,'shortener');if(!$c||empty($c['enabled'])||empty($c['shortener_url'])||empty($c['shortener_api_key']))return $url;$ch=curl_init(rtrim($c['shortener_url'],'/').'?'.http_build_query(['api'=>$c['shortener_api_key'],'url'=>$url,'format'=>'json']));curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>10]);$r=curl_exec($ch);$err=curl_error($ch);curl_close($ch);if($r===false)fail('Shortener API failed: '.$err,502);$d=json_decode($r,true);if(!is_array($d)||($d['status']??'')!=='success'||empty($d['shortenedUrl']))fail('Shortener returned an error.',400);return $d['shortenedUrl'];}
function captcha_valid(string $v):bool{if(!defined('HCAPTCHA_SECRET')||HCAPTCHA_SECRET==='')return false;$ch=curl_init('https://api.hcaptcha.com/siteverify');curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>http_build_query(['secret'=>HCAPTCHA_SECRET,'response'=>$v,'remoteip'=>request_ip()]),CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>12]);$r=curl_exec($ch);curl_close($ch);$d=json_decode((string)$r,true);return is_array($d)&&!empty($d['success']);}
function render_verify(string $token,string $endpoint):never{$site=defined('HCAPTCHA_SITEKEY')?esc(HCAPTCHA_SITEKEY):'';$t=esc($token);$ep=esc($endpoint);header('Content-Type:text/html; charset=utf-8');echo '<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Verify - Anti Bypass</title><script src="https://js.hcaptcha.com/1/api.js" async defer></script><style>body{margin:0;min-height:100vh;display:grid;place-items:center;background:#080b14;color:#edf3ff;font:15px system-ui}.card{width:min(390px,calc(100% - 40px));padding:28px;border:1px solid #26334b;border-radius:18px;background:#101827;text-align:center}button{width:100%;padding:13px;margin-top:20px;border:0;border-radius:10px;background:#09b9d5;font-weight:700}button:disabled{opacity:.4}</style></head><body><main class="card"><h2>Anti Bypass</h2><h1>Verify Access</h1><p>Complete CAPTCHA to continue.</p><div class="h-captcha" data-sitekey="'.$site.'" data-callback="solved"></div><button id="go" disabled onclick="verifyNow()">Continue</button><p id="msg"></p></main><script>let cap="";function solved(v){cap=v;document.getElementById("go").disabled=false}async function verifyNow(){let b=document.getElementById("go");b.disabled=true;b.textContent="Verifying...";try{let r=await fetch("'.$ep.'",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({cap:cap,t:"'.$t.'"})});let d=await r.json();if(!r.ok||!d.ok)throw Error(d.detail||"Verification failed");location.href=d.redirect||("/p?s="+encodeURIComponent(d.sid))}catch(x){document.getElementById("msg").textContent=x.message;b.disabled=false;b.textContent="Try Again"}}</script></body></html>';exit;}
